const alerta = $('Code in JavaScript').first().json;

// Resultado produzido pela IA
const analiseIA = $json.output ?? $json.text ?? "Não foi possível gerar a análise da IA.";

// Recomendações definidas pelo fluxo, sem depender da IA
let recomendacao = "Verificar se a ação registrada foi autorizada.";

if (alerta.rule_id === "100003") {
  recomendacao = [
    "Confirmar se a criação ou ativação da conta foi autorizada.",
    "Verificar quem realizou a ação registrada no evento.",
    "Verificar atividades posteriores associadas à conta."
  ].join("\n");
}

const relatorio = `🚨 ALERTA DE SEGURANÇA

📋 IDENTIFICAÇÃO

Severidade Wazuh: ${alerta.severity}
Regra: ${alerta.rule_id} - ${alerta.rule_description}
Endpoint: ${alerta.endpoint}
IP do Endpoint: ${alerta.endpoint_ip}
Usuário afetado: ${alerta.target_user}
Usuário responsável: ${alerta.subject_user}
Data/Hora: ${alerta.timestamp}
Evento Windows: ${alerta.event_id}
Canal: ${alerta.channel}

🧠 ANÁLISE ASSISTIDA POR IA

${analiseIA}

🛠️ RECOMENDAÇÕES

${recomendacao}

📌 DADOS TÉCNICOS

Computer: ${alerta.computer}
Provider: ${alerta.provider}
Resultado da auditoria: ${alerta.severity_value}
Ocorrências da regra: ${alerta.fired_times}
`;

return {
  json: {
    ...alerta,
    ai_analysis: analiseIA,
    report: relatorio
  }
};

const alerta = $('Code in JavaScript').first().json;

return {
  json: {
    ai_context: JSON.stringify(alerta, null, 2)
  }
};
